package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.util.List;
import java.util.Objects;
import net.officefloor.hq.app.rate.RateTable;

/** The due figures of claims and the due-total of a person's claims. */
public final class Dues {

    private Dues() {
    }

    /**
     * A claim's due: once settled, the due fixed then (its late charge frozen in); otherwise its
     * {@link #base} figure plus, while overdue, its {@link RateTable#lateCharge late charge}. Null when there
     * is none.
     */
    public static BigDecimal figure(Claim claim, String grade, RateTable rates) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        BigDecimal base = base(claim, grade, rates);
        if (base == null || !overdue(claim, rates)) {
            return base;
        }
        return base.add(rates.lateCharge(base, rates.dueBy(claim.getDate())));
    }

    /**
     * A claim's figure before any late charge: while bound by a statement, the figure bound then;
     * otherwise the amount at the rate for its person's grade in force on its date, but at least the
     * sheet's floor. Null when there is none. A statement binds this figure, never the late charge.
     */
    public static BigDecimal base(Claim claim, String grade, RateTable rates) {
        return claim.isStated() ? claim.getStatedDue()
                : rates.due(claim.getAmount(), grade, claim.getDate());
    }

    /** Whether the claim is overdue: OPEN, and due by a date before the sheet's today. */
    public static boolean overdue(Claim claim, RateTable rates) {
        return claim.getStatus() == ClaimStatus.OPEN && rates.dueBy(claim.getDate()).isBefore(rates.today());
    }

    /** The overdue claims that count, see {@link #overdue} and {@link #counts}. */
    public static List<Claim> overdue(List<Claim> claims, RateTable rates, boolean held) {
        return claims.stream().filter(c -> counts(c, held) && overdue(c, rates)).toList();
    }

    /** The sum of the due figures of the claims given (0.00 with none); a claim with none is skipped. */
    public static BigDecimal sum(String grade, List<Claim> claims, RateTable rates) {
        return claims.stream().map(c -> figure(c, grade, rates)).filter(Objects::nonNull)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    /** Whether the claim's figure is kept whatever the rates: fixed by settling or bound by a statement. */
    private static boolean kept(Claim claim) {
        return claim.getSettledDue() != null || (claim.isStated() && claim.getStatedDue() != null);
    }

    /**
     * Whether the claim counts in the live totals: OPEN and SETTLED claims do, except that the OPEN
     * claims of a person on hold count in none.
     */
    public static boolean counts(Claim claim, boolean held) {
        return claim.getStatus().counts() && !(held && claim.getStatus() == ClaimStatus.OPEN);
    }

    /**
     * The sum of the due figures of the claims that count (0.00 with none); a person not on hold.
     */
    public static BigDecimal total(String grade, List<Claim> claims, RateTable rates) {
        return total(grade, claims, rates, false);
    }

    /**
     * The sum of the due figures of the claims that count (0.00 with none), see {@link #counts}. Null (n/a) when the grade has
     * no rate on the sheet's today, unless a claim that counts keeps a figure: then it is the sum of the
     * figures there are.
     */
    public static BigDecimal total(String grade, List<Claim> claims, RateTable rates, boolean held) {
        List<Claim> counting = claims.stream().filter(c -> counts(c, held)).toList();
        boolean shown = rates.current(grade) != null || counting.stream().anyMatch(Dues::kept);
        return shown ? counting.stream().map(c -> figure(c, grade, rates))
                .filter(Objects::nonNull).reduce(BigDecimal.ZERO, BigDecimal::add) : null;
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.Comparator;
import java.util.List;

/**
 * Every rate on a sheet, the sheet's today, its floor, its terms and its late percent: which rate is in
 * force for a grade on a date, the live due it makes of an amount, the date a claim is due by, and the
 * late charge an overdue figure gains.
 */
public record RateTable(List<Rate> rates, LocalDate today, BigDecimal floor, int terms, BigDecimal latePct) {

    /** The days in each period overdue that adds the late percent once more. */
    private static final int LATE_PERIOD_DAYS = 30;

    /**
     * The percent in force for the grade on the date: the rate whose from-date is the latest one on
     * or before it, a rate with no from-date applying from the beginning of time; null when none does.
     */
    public BigDecimal on(String grade, LocalDate date) {
        return rates.stream()
                .filter(r -> r.getGrade().equals(grade))
                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .map(Rate::getPct).orElse(null);
    }

    /** The percent in force for the grade on the sheet's today; null when none is. */
    public BigDecimal current(String grade) {
        return on(grade, today);
    }

    /**
     * The live due of an amount dated on the date for the grade: the amount at the rate in force then,
     * but at least the floor; null when no rate is.
     */
    public BigDecimal due(BigDecimal amount, String grade, LocalDate date) {
        BigDecimal due = RateService.due(amount, on(grade, date));
        return due == null || floor == null || due.compareTo(floor) >= 0 ? due : floor;
    }

    /** The date a claim dated on the date is due by: the date plus the terms. */
    public LocalDate dueBy(LocalDate date) {
        return date.plusDays(terms);
    }

    /**
     * The late charge on a figure due by the date: the late percent of the figure for every full 30 days
     * from that date to the sheet's today, rounded like a due; 0.00 when not a full 30 days overdue.
     */
    public BigDecimal lateCharge(BigDecimal figure, LocalDate dueBy) {
        long periods = dueBy.isBefore(today) ? ChronoUnit.DAYS.between(dueBy, today) / LATE_PERIOD_DAYS : 0;
        BigDecimal pct = latePct == null ? BigDecimal.ZERO : latePct;
        return RateService.due(figure.multiply(BigDecimal.valueOf(periods)), pct);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Quick-add: a DRAFT claim of an amount, dated the sheet's today with an empty note, for the person
 * of a name, matched as the person form matches names; a name not on the sheet adds the person first
 * with grade A. The whole of it is one change: a refused claim leaves no new person behind.
 */
@Service
public class QuickAddService {

    private static final String GRADE = "A";

    private final PersonRepository people;
    private final PersonService persons;
    private final ClaimService claims;

    public QuickAddService(PersonRepository people, PersonService persons, ClaimService claims) {
        this.people = people;
        this.persons = persons;
        this.claims = claims;
    }

    /** Returns the person the claim belongs to. */
    @Transactional
    public long add(String sheetId, String user, String name, BigDecimal amount) {
        String trimmed = name.trim();
        Person person = people.findBySheetIdAndNameIgnoreCase(sheetId, trimmed)
                .orElseGet(() -> persons.add(sheetId, user, trimmed, GRADE));
        return claims.add(sheetId, user, person.getId(), amount, null, "");
    }
}

